#include <iostream>
#include <string_view>

struct Animal { virtual ~Animal() = default; virtual std::string_view sound() const { return "?"; } };
struct Dog : Animal { std::string_view sound() const override { return "woof"; } };
int main() { Dog dog; const Animal& animal = dog; std::cout << animal.sound() << '\n'; }
